fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Assuming a and b are of the same length as per the problem statement
    let n = a.len();
    let mut result = Vec::with_capacity(n); // Preallocate space for the result

    for i in 0..n {
        result.push(a[i] | b[i]); // Perform bitwise OR and push to result
    }

    result
}